Fixes: 0fe45467a104 ("idpf: add create vport and netdev configuration")
Signed-off-by: Emil Tantilov <emil.s.tantilov@intel.com>
Reviewed-by: Madhu Chittim <madhu.chittim@intel.com>
Tested-by: Samuel Salin <Samuel.salin@intel.com>
Signed-off-by: Tony Nguyen <anthony.l.nguyen@intel.com>

Here is the root cause:
During reset handling, the driver did not detach and close netdevs before de-allocating vport resources, leaving netdevs exposed to external callbacks (e.g., ifup/down, ethtool). This allowed races between concurrent resets and could lead to loss of netdev state (e.g., interface staying DOWN) or NULL pointer dereferences when callbacks accessed uninitialized resources after a failed reset. The previous approach of disabling Tx and carrier, then using `idpf_set_vport_state` to restore state after reset, was insufficient to protect against these races and crashes.

Here is the patch:

+static void idpf_detach_and_close(struct idpf_adapter *adapter)
+{
+	int max_vports = adapter->max_vports;
+
+	for (int i = 0; i < max_vports; i++) {
+		struct net_device *netdev = adapter->netdevs[i];
+
+		/* If the interface is in detached state, that means the
+		 * previous reset was not handled successfully for this
+		 * vport.
+		 */
+		if (!netif_device_present(netdev))
+			continue;
+
+		/* Hold RTNL to protect racing with callbacks */
+		rtnl_lock();
+		netif_device_detach(netdev);
+		if (netif_running(netdev)) {
+			set_bit(IDPF_VPORT_UP_REQUESTED,
+				adapter->vport_config[i]->flags);
+			dev_close(netdev);
+		}
+		rtnl_unlock();
+	}
+}
+
+static void idpf_attach_and_open(struct idpf_adapter *adapter)
+{
+	int max_vports = adapter->max_vports;
+
+	for (int i = 0; i < max_vports; i++) {
+		struct idpf_vport *vport = adapter->vports[i];
+		struct idpf_vport_config *vport_config;
+		struct net_device *netdev;
+
+		/* In case of a critical error in the init task, the vport
+		 * will be freed. Only continue to restore the netdevs
+		 * if the vport is allocated.
+		 */
+		if (!vport)
+			continue;
+
+		/* No need for RTNL on attach as this function is called
+		 * following detach and dev_close(). We do take RTNL for
+		 * dev_open() below as it can race with external callbacks
+		 * following the call to netif_device_attach().
+		 */
+		netdev = adapter->netdevs[i];
+		netif_device_attach(netdev);
+		vport_config = adapter->vport_config[vport->idx];
+		if (test_and_clear_bit(IDPF_VPORT_UP_REQUESTED,
+				       vport_config->flags)) {
+			rtnl_lock();
+			dev_open(netdev, NULL);
+			rtnl_unlock();
+		}
+	}
+}
+
 /**
  * idpf_cfg_netdev - Allocate, configure and register a netdev
  */
 static void idpf_vport_dealloc(struct idpf_vport *vport)
 {
 	struct idpf_adapter *adapter = vport->adapter;
 	unsigned int i = vport->idx;

 	idpf_idc_deinit_vport_aux_device(vport->vdev_info);

 	idpf_deinit_mac_addr(vport);
-	idpf_vport_stop(vport, true);

-	if (!test_bit(IDPF_HR_RESET_IN_PROG, adapter->flags))
+	if (!test_bit(IDPF_HR_RESET_IN_PROG, adapter->flags)) {
+		idpf_vport_stop(vport, true);
 		idpf_decfg_netdev(vport);
+	}
 	if (test_bit(IDPF_REMOVE_IN_PROG, adapter->flags))
 		idpf_del_all_mac_filters(vport);

 	if (adapter->netdevs[i]) {
 		struct idpf_netdev_priv *np = netdev_priv(adapter->netdevs[i]);

 		np->vport = NULL;
 	}

 	idpf_vport_rel(vport);

 	adapter->vports[i] = NULL;
 	adapter->next_vport = idpf_get_free_slot(adapter);
 }

  */
 void idpf_init_task(struct work_struct *work)
 {
 	struct idpf_vport_config *vport_config;
 	struct idpf_vport_max_q max_q;
 	struct idpf_adapter *adapter;
-	struct idpf_netdev_priv *np;
 	struct idpf_vport *vport;
 	u16 num_default_vports;
 	struct pci_dev *pdev;
 	bool default_vport;
 	int index, err;

 	adapter = container_of(work, struct idpf_adapter, init_task.work);

 	num_default_vports = idpf_get_default_vports(adapter);
 	if (adapter->num_alloc_vports < num_default_vports)
 		default_vport = true;
 	else
 		default_vport = false;

 	err = idpf_vport_alloc_max_qs(adapter, &max_q);
 	if (err)
 		goto unwind_vports;

 	err = idpf_send_create_vport_msg(adapter, &max_q);
 	if (err) {
 		idpf_vport_dealloc_max_qs(adapter, &max_q);
 		goto unwind_vports;
 	}

 	pdev = adapter->pdev;
 	vport = idpf_vport_alloc(adapter, &max_q);
 	if (!vport) {
 		err = -EFAULT;
 		dev_err(&pdev->dev, "failed to allocate vport: %d\n",
 			err);
 		idpf_vport_dealloc_max_qs(adapter, &max_q);
 		goto unwind_vports;
 	}

 	err = idpf_send_get_rx_ptype_msg(vport);
 	if (err)
 		goto unwind_vports;

 	index = vport->idx;
 	vport_config = adapter->vport_config[index];

 	spin_lock_init(&vport_config->mac_filter_list_lock);

 	INIT_LIST_HEAD(&vport_config->user_config.mac_filter_list);
 	INIT_LIST_HEAD(&vport_config->user_config.flow_steer_list);

 	err = idpf_check_supported_desc_ids(vport);
 	if (err) {
 		dev_err(&pdev->dev, "failed to get required descriptor ids\n");
 		goto unwind_vports;
 	}

 	if (idpf_cfg_netdev(vport))
 		goto unwind_vports;

-	/* Once state is put into DOWN, driver is ready for dev_open */
-	np = netdev_priv(vport->netdev);
-	clear_bit(IDPF_VPORT_UP, np->state);
-	if (test_and_clear_bit(IDPF_VPORT_UP_REQUESTED, vport_config->flags))
-		idpf_vport_open(vport, true);
-
 	/* Spawn and return 'idpf_init_task' work queue until all the
 	 * default vports are created
 	 */
 	if (adapter->num_alloc_vports < num_default_vports) {
 		queue_delayed_work(adapter->init_wq, &adapter->init_task,
 				   msecs_to_jiffies(5 * (adapter->pdev->devfn & 0x07)));

 		return;
 	}

 	for (index = 0; index < adapter->max_vports; index++) {
 		struct net_device *netdev = adapter->netdevs[index];
 		struct idpf_vport_config *vport_config;

 		vport_config = adapter->vport_config[index];

 		if (!netdev ||
 		    test_bit(IDPF_VPORT_REG_NETDEV, vport_config->flags))
 			continue;

 		err = register_netdev(netdev);
 		if (err) {
 			dev_err(&pdev->dev, "failed to register netdev for vport %d: %pe\n",
 				index, ERR_PTR(err));
 			continue;
 		}
 		set_bit(IDPF_VPORT_REG_NETDEV, vport_config->flags);
 	}

 	/* As all the required vports are created, clear the reset flag
 	 * unconditionally here in case we were in reset and the link was down.
 	 */
 	clear_bit(IDPF_HR_RESET_IN_PROG, adapter->flags);
 	/* Start the statistics task now */
 	queue_delayed_work(adapter->stats_wq, &adapter->stats_task,
 			   msecs_to_jiffies(10 * (pdev->devfn & 0x07)));

 	return;

 unwind_vports:
 	if (default_vport) {
 		for (index = 0; index < adapter->max_vports; index++) {
 			if (adapter->vports[index])
 				idpf_vport_dealloc(adapter->vports[index]);
 		}
 	}
 	clear_bit(IDPF_HR_RESET_IN_PROG, adapter->flags);
 }

 }

